    /// Add with carry, using the carry flag set by a previous flag-setting
    /// add: `rd = rn + rm + C`.
    pub fn adc_rrr(&mut self, rm: Reg, rn: Reg, rd: WritableReg, size: OperandSize) {
        self.alu_rrr(ALUOp::Adc, rm, rn, rd, size);
    }

    /// Subtract with three registers, setting flags and keeping the result in
    /// `rd`: `rd = rn - rm`.
    pub fn subs_rrr_dst(&mut self, rm: Reg, rn: Reg, rd: WritableReg, size: OperandSize) {
        self.alu_rrr_extend(ALUOp::SubS, rm, rn, rd, size, ExtendOp::UXTX);
    }

    /// Subtract with carry (borrow), using the carry flag set by a previous
    /// flag-setting subtract: `rd = rn - rm - !C`.
    pub fn sbc_rrr(&mut self, rm: Reg, rn: Reg, rd: WritableReg, size: OperandSize) {
        self.alu_rrr(ALUOp::Sbc, rm, rn, rd, size);
    }

    /// Signed multiply high: `rd = (rn * rm) >> 64`.
    pub fn smulh_rrr(&mut self, rm: Reg, rn: Reg, rd: WritableReg, size: OperandSize) {
        self.alu_rrr(ALUOp::SMulH, rm, rn, rd, size);
    }

    /// Unsigned multiply high: `rd = (rn * rm) >> 64`.
    pub fn umulh_rrr(&mut self, rm: Reg, rn: Reg, rd: WritableReg, size: OperandSize) {
        self.alu_rrr(ALUOp::UMulH, rm, rn, rd, size);
    }
